"use strict";

/**
 * M12d end-to-end signed synthetic release -> observed sealed child -> strictly
 * disposable source/SQLite owner. Linux CI ONLY. No real keys/task files.
 *
 * The keys and trust inputs are generated by the SAME TEST RUNNER. This is
 * functional wiring, NOT independently provisioned production trust.
 */
const assert = require("node:assert/strict");
const crypto = require("node:crypto");
const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");
const { spawnSync } = require("node:child_process");
const test = require("node:test");
const { verifySyntheticRelease, TrustRefusal } =
  require("./fixtures/TaskSignedReleaseVerifierM11y.cjs");

const ROOT = path.resolve(__dirname, "../..");
const HOST = path.join(__dirname, "fixtures/TaskBoundJournalChildM11w.py");
const OWNER = path.join(ROOT, "services/projects/TaskJsonGateCandidateM11l.py");
const DRIVER = path.join(__dirname, "fixtures/TaskSignedOwnerBoundaryM12d.py");
const hash = input => crypto.createHash("sha256").update(input).digest("hex");

function sampleDocument() {
  return {
    version: 3, nextId: 2, nextProjectId: 1, projects: [],
    tasks: [{
      id: "t1", title: "M11W_TEST_0", done: false, createdAtMs: 1000,
      updatedAtMs: 1000, priority: "none", description: "",
      dueDate: null, projectId: null
    }]
  };
}
function privateFile(file, bytes) {
  fs.writeFileSync(file, bytes, { mode: 0o600 });
  fs.chmodSync(file, 0o600);
}
function prepare() {
  const root = fs.mkdtempSync(path.join("/tmp", "m12d-root-"));
  fs.chmodSync(root, 0o700);
  const sourceDir = path.join(root, "m11l-tasks-copy");
  const releaseDir = path.join(root, "m11y-release-copy");
  fs.mkdirSync(sourceDir, { mode: 0o700 });
  fs.mkdirSync(releaseDir, { mode: 0o700 });
  const source = path.join(sourceDir, "todo-copy.json");
  privateFile(source, JSON.stringify(sampleDocument(), null, 2) + "\n");
  const baseline = fs.readFileSync(source);
  const host = fs.readFileSync(HOST);
  const owner = fs.readFileSync(OWNER);
  // Signed *descriptor* of the root-owned interpreter under test, not a
  // claim that the ephemeral CI signer is production-authoritative.
  const interpreter = Buffer.from(
    "M12D-SYNTHETIC-INTERPRETER-SHA256:" +
    hash(fs.readFileSync(fs.realpathSync("/usr/bin/python3"))) + "\n");
  const artifacts = {
    host: "synthetic-host.py", owner: "synthetic-owner.py",
    interpreter: "synthetic-interpreter.bin"
  };
  const bytes = { host, owner, interpreter };
  for (const role of Object.keys(artifacts)) {
    privateFile(path.join(releaseDir, artifacts[role]), bytes[role]);
  }
  const { publicKey, privateKey } = crypto.generateKeyPairSync("ed25519");
  const trust = {
    publicKeyPem: publicKey.export({ type: "spki", format: "pem" }),
    expectedSpkiHash: hash(publicKey.export({ type: "spki", format: "der" })),
    minimumGeneration: 7,
  };
  function resign(gen = 8) {
    const manifest = Buffer.from(
      "M11Y-SYNTHETIC-RELEASE-V1\n" +
      "generation:" + gen + "\n" +
      "host:" + hash(bytes.host) + "\n" +
      "owner:" + hash(bytes.owner) + "\n" +
      "interpreter:" + hash(bytes.interpreter) + "\n");
    privateFile(path.join(releaseDir, "release.manifest"), manifest);
    privateFile(path.join(releaseDir, "release.sig"),
      crypto.sign(null, manifest, privateKey));
  }
  resign();
  return {
    root, sourceDir, releaseDir, source, baseline, artifacts, bytes,
    trust, resign,
    overwrite(role, content) {
      bytes[role] = Buffer.from(content);
      privateFile(path.join(releaseDir, artifacts[role]), bytes[role]);
    },
    cleanup() { fs.rmSync(root, { recursive: true, force: true }); }
  };
}

function runDriver(fx, mode, options = {}) {
  let verified;
  if (options.raw) {
    verified = options.raw;
  } else {
    const trusted = options.trust === undefined ? fx.trust : options.trust;
    const release = verifySyntheticRelease(fx.releaseDir, trusted);
    assert.equal(release.status, "SYNTHETIC_SIGNED_CONTENT_VERIFIED");
    assert.equal(release.productionWriterAuthorized, false);
    verified = {
      mode, folder: options.folder || fx.sourceDir, signatureVerified: true,
      signedSnapshots: Object.fromEntries(
        Object.entries(release.snapshots).map(([k, v]) => [k, v.toString("base64")]))
    };
  }
  const proc = spawnSync("/usr/bin/python3", ["-B", DRIVER], {
    input: JSON.stringify(verified), encoding: "utf8", timeout: 12000,
    maxBuffer: 8192,
    env: { PATH: "/usr/bin:/bin", LANG: "C", PYTHONNOUSERSITE: "1" }
  });
  assert.equal(proc.error, undefined);
  assert.equal(proc.stderr, "", "Unexpected synthetic child stderr");
  const lines = proc.stdout.trim().split("\n");
  assert.equal(lines.length, 1, "Strict JSON frame");
  const response = JSON.parse(lines[0]);
  return { exit: proc.status, response };
}
function withFixture(fn) {
  const fx = prepare();
  try { return fn(fx); } finally { fx.cleanup(); }
}
function rejected(fx, code, trust = fx.trust) {
  assert.throws(() => verifySyntheticRelease(fx.releaseDir, trust),
    e => e instanceof TrustRefusal && e.message === code);
  assert.equal(fs.existsSync(path.join(fx.sourceDir, "gate-review.db")), false);
}
function denied(result) {
  assert.equal(result.exit, 2);
  assert.equal(result.response.status, "REFUSED");
  assert.equal(result.response.productionWriterAuthorized, false);
  assert.equal(result.response.realTaskDataAccess, false);
}

test("signed synthetic release binds to actual Linux child and durable disposable owner", () =>
  withFixture(fx => {
    const first = runDriver(fx, "NEW_RESERVE");
    assert.equal(first.exit, 0);
    assert.equal(first.response.status, "SYNTHETIC_SIGNED_OWNER_BOUND");
    assert.equal(first.response.epoch, 0);
    assert.equal(first.response.phase, "JSON_ACTIVE");
    assert.equal(first.response.pending, true);
    assert.equal(first.response.sourceUnchanged, true);
    assert.equal(first.response.backupVerified, true);
    assert.equal(first.response.processObservedByKernel, true);
    assert.equal(first.response.signedSnapshotsUsedWithoutPathReopen, true);
    assert.equal(first.response.productionWriterAuthorized, false);
    assert.equal(first.response.realTaskDataAccess, false);
    assert.deepEqual(fs.readFileSync(fx.source), fx.baseline);
    assert.deepEqual(fs.readFileSync(path.join(
      fx.sourceDir, "source-before-gate.bak")), fx.baseline);
    const next = runDriver(fx, "EXISTING_CHECK");
    assert.equal(next.exit, 0);
    assert.equal(next.response.phase, "RECOVERY_REVIEW");
    assert.equal(next.response.epoch, 1);
    assert.equal(next.response.pending, true);
    assert.deepEqual(fs.readFileSync(fx.source), fx.baseline);
  }));

test("missing independent test trust input, wrong key and release-supplied key refuse", () =>
  withFixture(fx => {
    rejected(fx, "INDEPENDENT_TRUST_ANCHOR_REQUIRED", {});
    const altered = { ...fx.trust, expectedSpkiHash: "0".repeat(64) };
    rejected(fx, "TRUST_ANCHOR_FINGERPRINT_MISMATCH", altered);
    privateFile(path.join(fx.releaseDir, "trusted-key.pem"),
                fx.trust.publicKeyPem);
    rejected(fx, "INDEPENDENT_TRUST_ANCHOR_REQUIRED", null);
  }));

test("tampered signed-release artifacts and signature fail before child launch", () =>
  withFixture(fx => {
    fx.overwrite("host", Buffer.concat([fx.bytes.host, Buffer.from("# tamper\n")]));
    rejected(fx, "RELEASE_ARTIFACT_DIGEST_MISMATCH");
  }));

test("synthetic Ed25519 signer approving foreign executable does not grant test execution", () =>
  withFixture(fx => {
    fx.overwrite("host", Buffer.concat([fx.bytes.host, Buffer.from("# signed malicious change\n")]));
    fx.resign(); // Valid signature, different host source.
    const result = runDriver(fx, "NEW_RESERVE");
    denied(result);
    assert.equal(fs.existsSync(path.join(fx.sourceDir, "gate-review.db")), false);
    assert.deepEqual(fs.readFileSync(fx.source), fx.baseline);
  }));

test("signed altered owner module cannot change existing restricted implementation", () =>
  withFixture(fx => {
    fx.overwrite("owner", Buffer.concat([fx.bytes.owner, Buffer.from("\n# changed\n")]));
    fx.resign();
    const result = runDriver(fx, "NEW_RESERVE");
    denied(result);
    assert.equal(fs.existsSync(path.join(fx.sourceDir, "gate-review.db")), false);
  }));

test("signed wrong interpreter hash fails observed interpreter pin before spawn", () =>
  withFixture(fx => {
    fx.overwrite("interpreter",
      Buffer.from("M12D-SYNTHETIC-INTERPRETER-SHA256:"+"f".repeat(64)+"\n"));
    fx.resign();
    const result = runDriver(fx, "NEW_RESERVE");
    denied(result);
    assert.equal(fs.existsSync(path.join(fx.sourceDir, "gate-review.db")), false);
  }));

test("signed malformed interpreter descriptor and stale release generation refuse", () =>
  withFixture(fx => {
    fx.overwrite("interpreter", Buffer.from("trust-me\n"));
    fx.resign();
    denied(runDriver(fx, "NEW_RESERVE"));
    fx.resign(7);
    rejected(fx, "RELEASE_GENERATION_NOT_NEWER");
  }));

test("wrong source folder, symlink and changed source seed denied", () =>
  withFixture(fx => {
    const wrong = path.join(fx.root, "not-m11l-tasks-copy");
    fs.mkdirSync(wrong, { mode: 0o700 });
    denied(runDriver(fx, "NEW_RESERVE", { folder: wrong }));
    assert.equal(fs.existsSync(path.join(fx.sourceDir, "gate-review.db")), false);
    privateFile(fx.source, JSON.stringify(sampleDocument()).replace(
      "M11W_TEST_0", "OTHER_SYNTHETIC") + "\n");
    denied(runDriver(fx, "NEW_RESERVE"));
    assert.equal(fs.existsSync(path.join(fx.sourceDir, "gate-review.db")), false);
  }));

test("a fake unverified signed-snapshot handoff is denied", () =>
  withFixture(fx => {
    const preVerified = verifySyntheticRelease(fx.releaseDir, fx.trust);
    const payload = {
      mode: "NEW_RESERVE", folder: fx.sourceDir,
      signatureVerified: false,
      signedSnapshots: Object.fromEntries(
        Object.entries(preVerified.snapshots).map(
          ([k, v]) => [k, v.toString("base64")]))
    };
    denied(runDriver(fx, "NEW_RESERVE", { raw: payload }));
    assert.equal(fs.existsSync(path.join(fx.sourceDir, "gate-review.db")), false);
  }));

test("real production singleton, shell and prior private source boundaries unchanged", () => {
  const store = fs.readFileSync(path.join(ROOT, "services/hub/ApolloHubTodoStore.qml"), "utf8");
  const shell = fs.readFileSync(path.join(ROOT, "shell.qml"), "utf8");
  const runner = fs.readFileSync(DRIVER, "utf8");
  assert.ok(store.includes("readonly property bool guardedWriterEnabled: false"));
  assert.equal((store.match(/\bFileView\s*\{/g) || []).length, 1);
  assert.equal((store.match(/return stage\(TodoPolicy\./g) || []).length, 9);
  assert.equal(store.includes("TaskSignedOwnerBoundaryM12d"), false);
  assert.equal(shell.includes("TaskSignedOwnerBoundaryM12d"), false);
  assert.equal(runner.includes("Quickshell.dataDir"), false);
  assert.equal(runner.includes("apollo-hub-todo-v1.json"), false);
});
